from pathlib import Path
import json
import dash
from dash import html,dcc,Input,Output,callback
import pandas as pd
import plotly.express as px

dash.register_page(__name__,path='/datos',name='Datos y EDA')
P=Path(__file__).resolve().parents[1]/'data/proyecto'
classes=pd.read_csv(P/'clases.csv'); quality=pd.read_csv(P/'calidad_histogramas.csv'); domain=json.loads((P/'dominio.json').read_text())
fig=px.bar(classes,x='clase',y='incluidas',color='particion',barmode='group',template='plotly_white',labels={'incluidas':'Recortes incluidos','clase':'Clase','particion':'Partición'});fig.update_layout(margin=dict(t=20))
d=domain['atipicos']; pf=px.bar(x=list(d['pacientes_por_grupo']),y=list(d['pacientes_por_grupo'].values()),text_auto=True,template='plotly_white',labels={'x':'Partición','y':'Pacientes'})
layout=html.Div([html.Span('DATOS / EXPLORACIÓN / CALIDAD',className='eyebrow'),html.H1('La muestra detrás de cada métrica.'),html.P('EDA heredado de E1, ampliado en E2 y reutilizado como contexto de E3. Las cifras conservan el corte de su fuente; no sustituyen el manifiesto de entrenamiento vigente.',className='lead'),html.Div([html.Div([html.H2('3'),html.P('clases nucleares')],className='card'),html.Div([html.H2('104'),html.P('pacientes en diagnóstico de dominio')],className='card'),html.Div([html.H2('6'),html.P('pacientes de reserva histórica E2')],className='card')],className='grid'),html.Section([html.H2('Distribución por clase y partición'),dcc.Graph(figure=fig),html.P('Fuente: selección de clases E1. Este corte contiene 14.428 recortes de entrenamiento; el piloto E3 usa su propio manifiesto verificado. No se mezclan denominadores.',className='note')],className='panel'),html.Div([html.Section([html.H2('Unidad de independencia'),dcc.Graph(figure=pf),html.P('Varios recortes pertenecen al mismo paciente. El remuestreo por paciente responde a una pregunta distinta de la variación entre semillas.')],className='panel'),html.Section([html.H2('Señal de dominio'),dcc.Graph(figure=px.bar(x=['Dominio (2 clases)','Sitio (8 clases)'],y=[domain['dominio']['balanced_accuracy'],domain['sitio']['balanced_accuracy']],text_auto='.3f',labels={'x':'Tarea diagnóstica','y':'Balanced accuracy OOF'},template='plotly_white')),html.P('Diagnóstico exploratorio OOF: 104 pacientes para dominio y 77 para sitio. Estas tareas difieren en número de clases; no comparar sus alturas como un ranking de modelos.')],className='panel')],className='two-col'),html.Section([html.H2('Calidad de imagen: explorar distribuciones'),html.Label('Característica'),dcc.Dropdown(id='quality-feature',options=[{'label':x.replace('_',' '),'value':x} for x in quality.variable.unique()],value='laplaciano_var',clearable=False),dcc.Graph(id='quality-hist'),html.P('Histogramas agregados del inventario de calidad E1. No se publican identificadores de pacientes. Una cola extrema prioriza revisión; no justifica excluir imágenes automáticamente.',className='note')],className='panel'),html.Section([html.H2('Galería y ejemplos documentados'),html.P('Las galerías originales conservan sus etiquetas, selección y procedencia. Consúltelas junto con el análisis acumulado; no son predicciones del nuevo modelo.'),html.A('Abrir galería E1',href='https://nucls-andres-duarte.onrender.com',target='_blank',className='button'),html.A('Abrir evidencia visual E2',href='https://nucls-entregable2.onrender.com/dashboard/index.html',target='_blank',className='button secondary')],className='panel')])
@callback(Output('quality-hist','figure'),Input('quality-feature','value'))
def histogram(feature):
 d=quality[quality.variable==feature]; f=px.bar(d,x='centro',y='cantidad',template='plotly_white',labels={'centro':feature.replace('_',' '),'cantidad':'Imágenes por intervalo'}); f.update_traces(marker_color='#087f8c');return f
